-- retail-sales-forecasting analytics mart (DuckDB)
-- Source: data/retail_sales_daily.csv (synthetic data, generated by data/generate_data.py)
-- Builds three marts from the raw daily grain:
--   mart_daily_sales             daily totals + units + promo-day flag
--   mart_store_category_monthly  monthly rollup by store & category, with MoM growth (LAG)
--   mart_promo_lift              promo vs non-promo average daily revenue by category

DROP TABLE IF EXISTS raw_sales;
CREATE OR REPLACE TABLE raw_sales AS
SELECT
    CAST(date AS DATE)      AS sale_date,
    store_id,
    category,
    units_sold,
    revenue,
    CAST(on_promotion AS BOOLEAN) AS on_promotion
FROM read_csv('data/retail_sales_daily.csv', header = true);

DROP TABLE IF EXISTS mart_daily_sales;
CREATE OR REPLACE TABLE mart_daily_sales AS
SELECT
    sale_date,
    COUNT(*)                                    AS n_store_category_rows,
    SUM(units_sold)                             AS total_units,
    ROUND(SUM(revenue), 2)                      AS total_revenue,
    ROUND(AVG(revenue), 2)                      AS avg_revenue_per_row,
    MAX(CASE WHEN on_promotion THEN 1 ELSE 0 END) AS had_promotion
FROM raw_sales
GROUP BY sale_date
ORDER BY sale_date;

DROP TABLE IF EXISTS mart_store_category_monthly;
CREATE OR REPLACE TABLE mart_store_category_monthly AS
WITH monthly AS (
    SELECT
        date_trunc('month', sale_date)::DATE AS month,
        store_id,
        category,
        SUM(units_sold)        AS units,
        ROUND(SUM(revenue), 2)  AS revenue,
        COUNT(DISTINCT sale_date) AS days_with_sales
    FROM raw_sales
    GROUP BY 1, 2, 3
)
SELECT
    month,
    store_id,
    category,
    units,
    revenue,
    days_with_sales,
    ROUND(
        100.0 * (revenue - LAG(revenue) OVER w) / NULLIF(LAG(revenue) OVER w, 0),
        2
    ) AS mom_revenue_growth_pct
FROM monthly
WINDOW w AS (PARTITION BY store_id, category ORDER BY month)
ORDER BY month, store_id, category;

DROP TABLE IF EXISTS mart_promo_lift;
CREATE OR REPLACE TABLE mart_promo_lift AS
WITH daily_cat AS (
    SELECT
        sale_date,
        category,
        SUM(units_sold) AS units,
        SUM(revenue)    AS revenue,
        MAX(CASE WHEN on_promotion THEN 1 ELSE 0 END) AS any_promo
    FROM raw_sales
    GROUP BY 1, 2
)
SELECT
    category,
    COUNT(DISTINCT CASE WHEN any_promo = 1 THEN sale_date END) AS promo_days,
    COUNT(DISTINCT CASE WHEN any_promo = 0 THEN sale_date END) AS non_promo_days,
    ROUND(AVG(CASE WHEN any_promo = 1 THEN revenue END), 2)    AS avg_daily_revenue_promo,
    ROUND(AVG(CASE WHEN any_promo = 0 THEN revenue END), 2)    AS avg_daily_revenue_no_promo,
    ROUND(
        100.0 * (AVG(CASE WHEN any_promo = 1 THEN revenue END)
               - AVG(CASE WHEN any_promo = 0 THEN revenue END))
        / NULLIF(AVG(CASE WHEN any_promo = 0 THEN revenue END), 0),
        2
    ) AS promo_lift_pct
FROM daily_cat
GROUP BY category
ORDER BY promo_lift_pct DESC;
